#!/usr/bin/env python3
import argparse
from base64 import b64decode
from pathlib import Path

PAYLOAD = ""

parser = argparse.ArgumentParser()
parser.add_argument("--check", action="store_true")
args = parser.parse_args()

target = Path("research-notes/FOUR_TO_ONE_EXCESS_BOUND.md")
expected = b64decode(PAYLOAD)
if args.check:
    if not target.is_file() or target.read_bytes() != expected:
        raise SystemExit("four-to-one proof note is not synchronized")
    print("four-to-one proof note synchronization: PASS")
else:
    target.write_bytes(expected)
    print("four-to-one proof note materialized: PASS")
